int megasas_alloc_cmds(struct megasas_instance *instance)
{
    int i;
    struct megasas_cmd **cmd_list;

    cmd_list = kzalloc(instance->max_num_cmd * sizeof(*cmd_list), GFP_KERNEL);
    if (!cmd_list) {
        dev_err(&instance->pdev->dev, "Failed to allocate command list\n");
        return -ENOMEM;
    }

    for (i = 0; i < instance->max_num_cmd; i++) {
        struct megasas_cmd *cmd;

        cmd = kzalloc(sizeof(*cmd), GFP_KERNEL);
        if (!cmd) {
            dev_err(&instance->pdev->dev, "Failed to allocate command structure\n");
            while (i--)
                kfree(cmd_list[i]);
            kfree(cmd_list);
            return -ENOMEM;
        }

        cmd->index = i;
        cmd->instance = instance;
        INIT_LIST_HEAD(&cmd->list);
        list_add_tail(&cmd->list, &instance->cmd_pool);
        cmd_list[i] = cmd;
    }

    if (megasas_create_frame_pool(instance) != 0) {
        for (i = 0; i < instance->max_num_cmd; i++)
            kfree(cmd_list[i]);
        kfree(cmd_list);
        return -ENOMEM;
    }

    return 0;
}

